// Leaflet's script and styles, for the Android map (src/ui/maps.android.tsx).
// Android maps need a Google Maps key; the app draws OpenStreetMap with Leaflet instead,
// as the website does, so the map ships inside the app rather than loading from a CDN.
// Rerun after updating leaflet in the website, in a normal terminal:
//   cd ~/stugora/mobile && npm run build:leaflet
import { readFileSync, writeFileSync } from "node:fs";

const dist = new URL("../../frontend/node_modules/leaflet/dist/", import.meta.url);
const js = readFileSync(new URL("leaflet.js", dist), "utf8").replace(/\n\/\/# sourceMappingURL=.*$/m, "");
const css = readFileSync(new URL("leaflet.css", dist), "utf8");
const { version } = JSON.parse(readFileSync(new URL("../package.json", dist), "utf8"));
const out = `// Generated by scripts/build-leaflet.mjs from Leaflet ${version} (BSD-2-Clause). Do not edit by hand.
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
`;
writeFileSync(new URL("../src/ui/leaflet.generated.ts", import.meta.url), out);
console.log(`leaflet ${version}: ${Math.round((js.length + css.length) / 1024)} kB`);
